
(()=>{const TAWUNIYA_ID='tawuniya-internal-guide';const TAWUNIYA_SRC_DOC=(()=>{const bytes=Uint8Array.from(atob(''),char=>char.charCodeAt(0));return new TextDecoder('utf-8').decode(bytes)})();if(!navigation.some(item=>item[0]===TAWUNIYA_ID))navigation.splice(Math.max(0,navigation.length-1),0,[TAWUNIYA_ID,'📚','Guidelines360']);else{const existing=navigation.find(item=>item[0]===TAWUNIYA_ID);if(existing)existing[2]='Guidelines360';}const previousRender=render;function tawuniyaPage(){return `<section class="tawuniya-shell" aria-label="Guidelines360"><iframe id="tawuniyaGuideFrame" title="Guidelines360"></iframe></section>`}render=function(){if(state.active===TAWUNIYA_ID){document.getElementById('sidebar').innerHTML=sidebar();content.innerHTML=tawuniyaPage();const frame=document.getElementById('tawuniyaGuideFrame');if(frame){frame.srcdoc=TAWUNIYA_SRC_DOC; frame.addEventListener('load',()=>{const d=frame.contentDocument;if(!d||d.getElementById('preauth-guidelines-db-search'))return;const w=d.createElement('div');w.id='preauth-guidelines-db-search';w.style.cssText='margin:8px 0;padding:8px;border:1px solid #d8b4e2;border-radius:9px;background:#fff;display:flex;align-items:center;gap:7px;flex-wrap:wrap;';w.innerHTML='<label style=\"font-weight:800;color:#35566a;font-size:11px\">Search manually uploaded files</label><input id=\"preauthGuidelinesDbSearchInput\" type=\"search\" placeholder=\"Search manually uploaded files by letter, word, number, title, or file name...\" style=\"flex:1;min-width:170px;padding:7px 9px;border:1px solid #b9ded9;border-radius:7px;background:#fbffff;color:#173c55;font-size:11px\"><span id=\"preauthGuidelinesDbSearchCount\" style=\"font-size:10px;color:#66808e\">0 manual files</span>';const a=d.querySelector('#idbFile')||d.querySelector('#idbGuideline');(a?.parentElement||d.body).insertBefore(w,a?.parentElement?.firstChild||null);const i=w.querySelector('input'),c=w.querySelector('span'),l=d.querySelector('#idbList');const apply=()=>{const q=(i.value||'').trim().toLocaleLowerCase();let n=0;[...(l?.children||[])].filter(x=>!x.classList.contains('idb-empty')).forEach(x=>{const hit=!q||(x.innerText||'').toLocaleLowerCase().includes(q);x.style.display=hit?'':'none';if(hit)n++});c.textContent=n+' matching manual files'};i.addEventListener('input',apply);if(l)new MutationObserver(apply).observe(l,{childList:true,subtree:true});apply()})}bind();return}return previousRender()};if(state.active===TAWUNIYA_ID)render()})();
